// Sheet columns: campaign_id | campaign | language | headline | body | cta | background
// The sheet holds content only. The project, templates and ratios are chosen in the forms.
// One row = one campaign in one language; n languages = n rows with the same campaign_id.
// A cell left empty is not sent, so the design keeps its default for that layer.
// A cell containing only "-" hides the layer (the renderer treats "" as hidden).
const form = $('Creative form').first().json;
const projects = $('Get projects').first().json.projects;
const projectName = $('Choose project').first().json.Project;
const projectId = projects.find((p) => p.name === projectName)?.id;
if (!projectId) throw new Error(`Project "${projectName}" is no longer in Creatives.`);
const picked = $('Choose creatives').first().json.Creatives;
const creatives = (Array.isArray(picked) ? picked : [picked]).map((v) => {
  const i = String(v).lastIndexOf('/');
  return { template: v.slice(0, i), ratio: v.slice(i + 1) };
});

const slug = (s) => String(s ?? '').trim().replace(/\s+/g, '-').toLowerCase();
const wantCampaign = slug(form.Campaign);
const wantLanguages = String(form.Languages ?? '').split(',').map(slug).filter(Boolean);
const stamp = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');

// Content columns -> layer keys in the design (#headline, #body, #cta, #background).
const FIELDS = ['headline', 'body', 'cta', 'background'];
const cell = (row, name) => {
  const key = Object.keys(row).find((k) => k.trim().toLowerCase() === name);
  const value = key === undefined ? '' : String(row[key] ?? '').trim();
  return value === '-' ? '' : value === '' ? undefined : value;
};

// The sheet must be the Creatives table: these columns are always present and filled. The content
// columns can be left blank per row, or empty for the whole table, so they are not required here.
const TABLE = ['campaign_id', 'campaign', 'language', 'headline', 'body', 'cta', 'background'];
const REQUIRED = ['campaign_id', 'campaign', 'language'];
const headers = new Set($input.all().flatMap((i) => Object.keys(i.json)).map((k) => k.trim().toLowerCase()));
const missing = REQUIRED.filter((c) => !headers.has(c));
if (missing.length) throw new Error(`The sheet is not in the expected table format. Missing columns: ${missing.join(', ')}. Expected: ${TABLE.join(' | ')}`);

const jobs = [];
for (const item of $input.all()) {
  const row = item.json;
  const campaignId = slug(cell(row, 'campaign_id'));
  const campaignName = slug(cell(row, 'campaign'));
  if (!campaignId && !campaignName) continue; // blank or spacer row
  const language = slug(cell(row, 'language') ?? 'default');
  if (wantCampaign && wantCampaign !== campaignId && wantCampaign !== campaignName) continue;
  if (wantLanguages.length && !wantLanguages.includes(language)) continue;

  const data = {};
  for (const field of FIELDS) {
    const value = cell(row, field);
    if (value !== undefined) data[field] = value;
  }
  for (const { template, ratio } of creatives) {
    jobs.push({
      json: { projectId, template, ratio, data, language, fileName: `${campaignId || campaignName}_${template}_${language}_${ratio}_${stamp}.png` },
    });
  }
}
if (!jobs.length) throw new Error('No sheet rows matched the campaign and languages you entered.');
return jobs;
